CREATE FUNCTION public.count_low_stock_materials(p_min_stock integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_count INT;
BEGIN
    SELECT COUNT(*)
    INTO v_count
    FROM rawmaterial
    WHERE stock_quantity < p_min_stock;

    RETURN v_count;
END;
$$;


