--
-- TOC entry 259 (class 1255 OID 65539)
-- Name: create_supply_order_for_supplier(integer, numeric); Type: PROCEDURE; Schema: public; Owner: Chani
--

CREATE PROCEDURE public.create_supply_order_for_supplier(IN p_supplier_id integer, IN p_initial_total numeric DEFAULT 0)
    LANGUAGE plpgsql
    AS $$
DECLARE
    supplier_exists INT;
    new_order_id INT;
    supplier_material RECORD;
BEGIN
    -- Check if supplier exists
    SELECT COUNT(*)
    INTO supplier_exists
    FROM supplier
    WHERE s_id = p_supplier_id;

    IF supplier_exists = 0 THEN
        RAISE EXCEPTION 'Supplier with id % does not exist', p_supplier_id;
    END IF;

    -- Print supplier materials using implicit cursor
    FOR supplier_material IN
        SELECT r_id, unit_price
        FROM supplied_by
        WHERE supplier_id = p_supplier_id
    LOOP
        RAISE NOTICE 'Supplier % supplies raw material % with unit price %',
            p_supplier_id,
            supplier_material.r_id,
            supplier_material.unit_price;
    END LOOP;

    -- Create new order id manually
    SELECT COALESCE(MAX(order_id), 0) + 1
    INTO new_order_id
    FROM supplyorder;

    -- Insert new supply order
        order_id,
        order_date,
        total,
        order_status,
        s_id,
        updated_at
    )
    VALUES (
        new_order_id,
        CURRENT_DATE,
        p_initial_total,
        'Pending',
        p_supplier_id,
        CURRENT_TIMESTAMP
    );

    RAISE NOTICE 'New supply order % was created for supplier %',
        new_order_id,
        p_supplier_id;

EXCEPTION
    WHEN OTHERS THEN
        RAISE EXCEPTION 'Error in create_supply_order_for_supplier: %', SQLERRM;
END;
$$;


ALTER PROCEDURE public.create_supply_order_for_supplier(IN p_supplier_id integer, IN p_initial_total numeric) OWNER TO "Chani";

