-- Name: log_supply_order_status_update(); Type: FUNCTION; Schema: public; Owner: Chani
--

CREATE FUNCTION public.log_supply_order_status_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Insert into log table only if the status was changed
    IF OLD.order_status IS DISTINCT FROM NEW.order_status THEN

        -- Update the order modification time
        NEW.updated_at := CURRENT_TIMESTAMP;

        -- Save the status change in the log table
            order_id,
            old_status,
            new_status,
            change_date
        )
        VALUES (
            OLD.order_id,
            OLD.order_status,
            NEW.order_status,
            CURRENT_TIMESTAMP
        );
    END IF;

    RETURN NEW;

EXCEPTION
    WHEN OTHERS THEN
        RAISE EXCEPTION 'Error in log_supply_order_status_update trigger: %', SQLERRM;
END;
$$;


ALTER FUNCTION public.log_supply_order_status_update() OWNER TO "Chani";

--
-- TOC entry 245 (class 1255 OID 73752)
-- Name: process_product_price_update(); Type: FUNCTION; Schema: public; Owner: Chani
--

CREATE FUNCTION public.process_product_price_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Validation: Ensure price is positive
    IF NEW.P_price <= 0 THEN
        RAISE EXCEPTION 'Business Rule Violation: Product price must be positive. Attempted value: %', NEW.P_price;
    END IF;

    -- Logging: Only if the price actually changed
    IF OLD.P_price IS DISTINCT FROM NEW.P_price THEN
        VALUES (OLD.P_id, OLD.P_price, NEW.P_price, current_user);
    END IF;

    RETURN NEW;

EXCEPTION
    WHEN OTHERS THEN
        RAISE EXCEPTION 'Critical error in process_product_price_update: %', SQLERRM;
END;
$$;


ALTER FUNCTION public.process_product_price_update() OWNER TO "Chani";

--
-- TOC entry 243 (class 1255 OID 65542)
-- Name: refill_low_stock_materials(integer, integer); Type: PROCEDURE; Schema: public; Owner: Chani
--

CREATE PROCEDURE public.refill_low_stock_materials(IN p_min_stock integer, IN p_add_amount integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_material RECORD;
    v_updated_count INT := 0;

    cur_low_stock CURSOR FOR
        SELECT r_id, r_name, stock_quantity
        FROM rawmaterial
        WHERE stock_quantity < p_min_stock;
BEGIN
    FOR v_material IN cur_low_stock LOOP
        UPDATE rawmaterial
        SET stock_quantity = stock_quantity + p_add_amount
        WHERE r_id = v_material.r_id;

        v_updated_count := v_updated_count + 1;
    END LOOP;

    RAISE NOTICE 'Updated % low stock materials.', v_updated_count;

EXCEPTION
    WHEN OTHERS THEN
        RAISE NOTICE 'Error while updating low stock materials: %', SQLERRM;
END;
$$;


ALTER PROCEDURE public.refill_low_stock_materials(IN p_min_stock integer, IN p_add_amount integer) OWNER TO "Chani";

